  if A.length ≥ 2 ∧ x ≥ 0 ∧ (∀ a ∈ A, a ≥ 0) then
    let A0 := if A[0]! > x then x else A[0]!
    let cnt0 := if A[0]! > x then A[0]! - x else 0
    ComputeOperationsFromIndex A x 1 (A0 :: A.tail) cnt0
  else 0

